import React, { useState } from "react";
import { motion } from "framer-motion";
import {
  Droplets,
  MapPin,
  Phone,
  Heart,
  Clock,
  CheckCircle,
  AlertTriangle,
  Users,
  Building,
} from "lucide-react";
import Notifications from "../components/common/Notifications";

const PatientDashboard = () => {
  const [currentStep, setCurrentStep] = useState(1);
  const [requestData, setRequestData] = useState({
    bloodType: "",
    quantity: "",
    location: "",
    urgency: "medium",
    contact: "",
    notes: "",
  });

  // Mock data for nearby hospitals and donors
  const nearbyOptions = [
    {
      id: 1,
      name: "City General Hospital",
      type: "hospital",
      distance: "2.5 km",
      bloodAvailable: ["O+", "B+", "A+"],
      contact: "+1 (555) 123-4567",
      availability: "high",
    },
    {
      id: 2,
      name: "John Smith",
      type: "donor",
      distance: "1.8 km",
      bloodType: "O+",
      contact: "+1 (555) 234-5678",
      availability: "available",
    },
    {
      id: 3,
      name: "St. Mary Medical Center",
      type: "hospital",
      distance: "4.2 km",
      bloodAvailable: ["O-", "A-", "B-"],
      contact: "+1 (555) 345-6789",
      availability: "limited",
    },
    {
      id: 4,
      name: "Emily Davis",
      type: "donor",
      distance: "3.1 km",
      bloodType: "O+",
      contact: "+1 (555) 456-7890",
      availability: "available",
    },
  ];

  const bloodTypes = ["A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"];

  const handleInputChange = (e) => {
    setRequestData({
      ...requestData,
      [e.target.name]: e.target.value,
    });
  };

  const handleNextStep = () => {
    if (currentStep < 3) {
      setCurrentStep(currentStep + 1);
    }
  };

  const handlePrevStep = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleSubmitRequest = () => {
    // In a real app, this would submit the request
    setCurrentStep(4); // Show results
  };

  const getAvailabilityColor = (status) => {
    switch (status) {
      case "high":
        return "text-green-400 bg-green-500/20 border border-green-500/30";
      case "available":
        return "text-green-400 bg-green-500/20 border border-green-500/30";
      case "limited":
        return "text-yellow-400 bg-yellow-500/20 border border-yellow-500/30";
      case "low":
        return "text-yellow-400 bg-yellow-500/20 border border-yellow-500/30";
      case "unavailable":
        return "text-red-400 bg-red-500/20 border border-red-500/30";
      default:
        return "text-gray-400 bg-gray-500/20 border border-gray-500/30";
    }
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
      },
    },
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: { duration: 0.5 },
    },
  };

  const progressSteps = [
    { number: 1, title: "Request Details" },
    { number: 2, title: "Location & Contact" },
    { number: 3, title: "Review & Submit" },
    { number: 4, title: "Results" },
  ];

  return (
    <div className="min-h-screen bg-gray-900">
      {/* Notifications */}
      <div className="fixed top-4 right-4 z-50">
        <Notifications />
      </div>

      {/* Header */}
      <motion.header
        initial={{ y: -100, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="glass-card m-6 rounded-2xl p-6 shadow-xl"
      >
        <div className="flex flex-col md:flex-row md:items-center md:justify-between">
          <div>
            <h1 className="text-3xl font-bold text-white">Patient Dashboard</h1>
            <p className="text-gray-300">
              Request blood donations in emergency situations
            </p>
          </div>
          <div className="mt-4 md:mt-0 flex items-center space-x-4">
            <div className="text-right">
              <p className="text-white font-medium">Emergency User</p>
              <p className="text-gray-400 text-sm">New York, NY</p>
            </div>
            <div className="w-12 h-12 bg-red-500 rounded-full flex items-center justify-center">
              <Heart className="w-6 h-6 text-white" />
            </div>
          </div>
        </div>
      </motion.header>

      {/* Progress Steps */}
      <motion.div
        initial={{ y: -50, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ delay: 0.1 }}
        className="mx-6 mb-6"
      >
        <div className="glass-card p-6 rounded-2xl">
          <div className="flex justify-between relative">
            {/* Progress bar background */}
            <div className="absolute top-4 left-0 right-0 h-1 bg-gray-700 z-0"></div>
            {/* Progress bar filled */}
            <div
              className="absolute top-4 left-0 h-1 bg-red-500 z-10 transition-all duration-500"
              style={{
                width: `${
                  ((currentStep - 1) / (progressSteps.length - 1)) * 100
                }%`,
              }}
            ></div>

            {progressSteps.map((step) => (
              <div
                key={step.number}
                className="flex flex-col items-center z-20"
              >
                <div
                  className={`w-8 h-8 rounded-full flex items-center justify-center mb-2 transition-all duration-300 ${
                    currentStep >= step.number
                      ? "bg-red-500 text-white"
                      : "bg-gray-700 text-gray-400"
                  }`}
                >
                  {currentStep > step.number ? (
                    <CheckCircle className="w-5 h-5" />
                  ) : (
                    step.number
                  )}
                </div>
                <span
                  className={`text-sm font-medium ${
                    currentStep >= step.number ? "text-white" : "text-gray-400"
                  }`}
                >
                  {step.title}
                </span>
              </div>
            ))}
          </div>
        </div>
      </motion.div>

      <motion.main
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="mx-6 mb-6"
      >
        {/* Step 1: Request Details */}
        {currentStep === 1 && (
          <motion.div
            variants={itemVariants}
            className="glass-card p-6 rounded-2xl"
          >
            <h2 className="text-2xl font-bold text-white mb-6">
              Blood Request Details
            </h2>
            <div className="space-y-6">
              <div>
                <label className="block text-sm font-medium text-gray-300 mb-2">
                  Blood Type Needed
                </label>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                  {bloodTypes.map((type) => (
                    <button
                      key={type}
                      onClick={() =>
                        setRequestData({ ...requestData, bloodType: type })
                      }
                      className={`p-3 rounded-xl border transition-all duration-200 ${
                        requestData.bloodType === type
                          ? "border-red-500 bg-red-500/20 text-white"
                          : "border-gray-600 bg-gray-800 text-gray-300 hover:border-gray-500"
                      }`}
                    >
                      {type}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300 mb-2">
                  Quantity Needed (Units)
                </label>
                <input
                  type="number"
                  name="quantity"
                  value={requestData.quantity}
                  onChange={handleInputChange}
                  min="1"
                  max="10"
                  className="w-full px-4 py-3 bg-gray-800 border border-gray-700 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-red-500 focus:border-transparent"
                  placeholder="Enter number of units needed"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300 mb-2">
                  Urgency Level
                </label>
                <div className="grid grid-cols-3 gap-3">
                  {[
                    {
                      value: "low",
                      label: "Low",
                      icon: <Clock className="w-4 h-4" />,
                    },
                    {
                      value: "medium",
                      label: "Medium",
                      icon: <Heart className="w-4 h-4" />,
                    },
                    {
                      value: "high",
                      label: "High",
                      icon: <AlertTriangle className="w-4 h-4" />,
                    },
                  ].map((level) => (
                    <button
                      key={level.value}
                      onClick={() =>
                        setRequestData({ ...requestData, urgency: level.value })
                      }
                      className={`p-3 rounded-xl border transition-all duration-200 flex flex-col items-center ${
                        requestData.urgency === level.value
                          ? "border-red-500 bg-red-500/20 text-white"
                          : "border-gray-600 bg-gray-800 text-gray-300 hover:border-gray-500"
                      }`}
                    >
                      {level.icon}
                      <span className="text-sm mt-1">{level.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300 mb-2">
                  Additional Notes
                </label>
                <textarea
                  name="notes"
                  value={requestData.notes}
                  onChange={handleInputChange}
                  rows="4"
                  className="w-full px-4 py-3 bg-gray-800 border border-gray-700 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-red-500 focus:border-transparent"
                  placeholder="Any additional information about the request..."
                ></textarea>
              </div>

              <div className="flex justify-end">
                <button
                  onClick={handleNextStep}
                  disabled={!requestData.bloodType || !requestData.quantity}
                  className={`px-6 py-3 rounded-lg font-medium transition-all duration-200 ${
                    requestData.bloodType && requestData.quantity
                      ? "bg-red-600 hover:bg-red-700 text-white"
                      : "bg-gray-700 text-gray-400 cursor-not-allowed"
                  }`}
                >
                  Continue to Location
                </button>
              </div>
            </div>
          </motion.div>
        )}

        {/* Step 2: Location & Contact */}
        {currentStep === 2 && (
          <motion.div
            variants={itemVariants}
            className="glass-card p-6 rounded-2xl"
          >
            <h2 className="text-2xl font-bold text-white mb-6">
              Location & Contact Information
            </h2>
            <div className="space-y-6">
              <div>
                <label className="block text-sm font-medium text-gray-300 mb-2">
                  Hospital/Location
                </label>
                <input
                  type="text"
                  name="location"
                  value={requestData.location}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 bg-gray-800 border border-gray-700 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-red-500 focus:border-transparent"
                  placeholder="Enter hospital name or address"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300 mb-2">
                  Contact Number
                </label>
                <input
                  type="tel"
                  name="contact"
                  value={requestData.contact}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 bg-gray-800 border border-gray-700 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-red-500 focus:border-transparent"
                  placeholder="Enter contact number"
                />
              </div>

              <div className="flex justify-between">
                <button
                  onClick={handlePrevStep}
                  className="px-6 py-3 bg-gray-700 hover:bg-gray-600 text-white rounded-lg font-medium transition-colors"
                >
                  Back
                </button>
                <button
                  onClick={handleNextStep}
                  disabled={!requestData.location || !requestData.contact}
                  className={`px-6 py-3 rounded-lg font-medium transition-all duration-200 ${
                    requestData.location && requestData.contact
                      ? "bg-red-600 hover:bg-red-700 text-white"
                      : "bg-gray-700 text-gray-400 cursor-not-allowed"
                  }`}
                >
                  Review Request
                </button>
              </div>
            </div>
          </motion.div>
        )}

        {/* Step 3: Review & Submit */}
        {currentStep === 3 && (
          <motion.div
            variants={itemVariants}
            className="glass-card p-6 rounded-2xl"
          >
            <h2 className="text-2xl font-bold text-white mb-6">
              Review Your Request
            </h2>
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="glass-card p-4 rounded-xl">
                  <h3 className="text-lg font-semibold text-white mb-3">
                    Request Details
                  </h3>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span className="text-gray-400">Blood Type:</span>
                      <span className="text-white font-medium">
                        {requestData.bloodType}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-400">Quantity:</span>
                      <span className="text-white font-medium">
                        {requestData.quantity} units
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-400">Urgency:</span>
                      <span
                        className={`font-medium ${
                          requestData.urgency === "high"
                            ? "text-red-400"
                            : requestData.urgency === "medium"
                            ? "text-yellow-400"
                            : "text-green-400"
                        }`}
                      >
                        {requestData.urgency.charAt(0).toUpperCase() +
                          requestData.urgency.slice(1)}
                      </span>
                    </div>
                  </div>
                </div>

                <div className="glass-card p-4 rounded-xl">
                  <h3 className="text-lg font-semibold text-white mb-3">
                    Location & Contact
                  </h3>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span className="text-gray-400">Location:</span>
                      <span className="text-white font-medium">
                        {requestData.location}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-400">Contact:</span>
                      <span className="text-white font-medium">
                        {requestData.contact}
                      </span>
                    </div>
                  </div>
                </div>
              </div>

              {requestData.notes && (
                <div className="glass-card p-4 rounded-xl">
                  <h3 className="text-lg font-semibold text-white mb-3">
                    Additional Notes
                  </h3>
                  <p className="text-gray-300">{requestData.notes}</p>
                </div>
              )}

              <div className="flex justify-between">
                <button
                  onClick={handlePrevStep}
                  className="px-6 py-3 bg-gray-700 hover:bg-gray-600 text-white rounded-lg font-medium transition-colors"
                >
                  Back
                </button>
                <button
                  onClick={handleSubmitRequest}
                  className="px-6 py-3 bg-red-600 hover:bg-red-700 text-white rounded-lg font-medium transition-colors flex items-center"
                >
                  <CheckCircle className="w-5 h-5 mr-2" />
                  Submit Emergency Request
                </button>
              </div>
            </div>
          </motion.div>
        )}

        {/* Step 4: Results */}
        {currentStep === 4 && (
          <motion.div variants={itemVariants} className="space-y-6">
            <div className="glass-card p-6 rounded-2xl">
              <div className="text-center mb-6">
                <CheckCircle className="w-16 h-16 text-green-400 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">
                  Request Submitted Successfully!
                </h2>
                <p className="text-gray-300">
                  Your emergency blood request has been sent to nearby hospitals
                  and donors
                </p>
              </div>

              <div className="bg-gradient-to-r from-red-500/10 to-red-600/10 p-4 rounded-xl mb-6">
                <div className="flex items-center">
                  <AlertTriangle className="w-5 h-5 text-red-400 mr-2" />
                  <span className="text-red-400 font-medium">
                    Request ID: LS-{Date.now().toString().slice(-6)}
                  </span>
                </div>
              </div>
            </div>

            <div className="glass-card p-6 rounded-2xl">
              <h2 className="text-2xl font-bold text-white mb-6">
                Nearby Matches
              </h2>
              <div className="space-y-4">
                {nearbyOptions.map((option, index) => (
                  <motion.div
                    key={option.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.1 }}
                    className="p-6 glass-card rounded-2xl flex items-center justify-between"
                  >
                    <div className="flex items-center">
                      <div className="mr-4">
                        {option.type === "hospital" ? (
                          <div className="w-12 h-12 bg-blue-500/20 rounded-full flex items-center justify-center">
                            <Building className="w-6 h-6 text-blue-400" />
                          </div>
                        ) : (
                          <div className="w-12 h-12 bg-green-500/20 rounded-full flex items-center justify-center">
                            <Users className="w-6 h-6 text-green-400" />
                          </div>
                        )}
                      </div>
                      <div>
                        <h3 className="text-lg font-semibold text-white">
                          {option.name}
                        </h3>
                        <div className="flex items-center text-gray-300 mt-1">
                          <MapPin className="w-4 h-4 mr-2" />
                          <span>{option.distance}</span>
                          <span className="mx-2">•</span>
                          <span
                            className={`px-2 py-1 rounded-full text-xs ${getAvailabilityColor(
                              option.availability
                            )}`}
                          >
                            {option.availability}
                          </span>
                        </div>
                        {option.type === "hospital" ? (
                          <div className="flex flex-wrap gap-1 mt-2">
                            {option.bloodAvailable.map((type, idx) => (
                              <span
                                key={idx}
                                className="px-2 py-1 bg-red-500/20 text-red-400 text-xs rounded"
                              >
                                {type}
                              </span>
                            ))}
                          </div>
                        ) : (
                          <div className="mt-2">
                            <span className="px-2 py-1 bg-red-500/20 text-red-400 text-xs rounded">
                              {option.bloodType}
                            </span>
                          </div>
                        )}
                      </div>
                    </div>
                    <div className="flex space-x-3">
                      <button className="flex items-center px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg transition-colors">
                        <Phone className="w-4 h-4 mr-2" />
                        Contact
                      </button>
                    </div>
                  </motion.div>
                ))}
              </div>
            </div>
          </motion.div>
        )}
      </motion.main>
    </div>
  );
};

export default PatientDashboard;
